#include <bits/stdc++.h>
using namespace std;

static long long K;
static unordered_map<unsigned long long, bool> memo;

bool win(long long a, long long b){
    if(a > b) swap(a, b); // exploit symmetry: w(a,b) == w(b,a)
    unsigned long long key = (((unsigned long long)a) << 32) | (unsigned long long)b;
    auto it = memo.find(key);
    if(it != memo.end()) return it->second;

    bool res = false;
    if(a == 0 && b == 0){
        res = false; // losing position
    } else if(K == 1){
        // For k=1, P-positions are exactly where both a and b are even
        res = !((a % 2 == 0) && (b % 2 == 0));
    } else {
        // Try moves: (a-1,b), (a,b-1), (a-k,b-k) if valid
        if(a >= 1 && !win(a-1, b)) res = true;
        if(!res && b >= 1 && !win(a, b-1)) res = true;
        if(!res && a >= K && b >= K && !win(a-K, b-K)) res = true;
    }

    memo[key] = res;
    return res;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t; long long k;
    if(!(cin >> t >> k)) return 0;
    K = k;
    for(int i = 0; i < t; ++i){
        long long n, m; cin >> n >> m;
        long long a = n - 1, b = m - 1;
        memo.clear();
        bool w = win(a, b);
        cout << (w ? '+' : '-') << "\n";
    }
    return 0;
}
